.hero-cmd {
      position: relative;
      min-height: 22rem;
      border: 1px dashed var(--is-border);
      border-radius: var(--is-radius);
      display: grid; place-items: center;
      text-align: center;
      padding: 1rem;
    }
    .hero-cmd h3 { margin: 0; font-size: 1.4rem; }
    .hero-cmd kbd {
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      font-size: .85rem;
      padding: .15rem .5rem;
      border-radius: 6px;
      border: 1px solid var(--is-border);
      background: var(--is-bg-elev);
    }
    .trigger-btn {
      margin-top: .85rem;
      font: inherit;
      padding: .55rem 1rem;
      border-radius: 999px;
      border: 1px solid var(--is-border);
      background: var(--is-bg-elev);
      color: inherit;
      cursor: pointer;
    }
    .trigger-btn:hover { border-color: var(--is-accent); color: var(--is-accent); }

